"""Validate durable wire history before resuming; never call tools or models."""
from copy import deepcopy
from .retry import assistant_message, format_repair, parse_turn, request_messages, FormatError


def validate_history(state, *, reasoning):
    def check(ok):
        if not ok: raise ValueError('Persisted OfficeQA request/history differs from saved responses')
    messages = deepcopy(state['initial']); calls = 0
    for n, rd in enumerate(state['rounds'], 1):
        check(rd['number'] == n and rd['phase'] in ('generation', 'tools', 'done'))
        check(n == len(state['rounds']) or rd['phase'] == 'done')
        repair = None; accepted = None; accepted_response = None
        for i, attempt in enumerate(rd['attempts'], 1):
            check(attempt['number'] == i and attempt['messages'] == request_messages(messages, repair))
            status = attempt['status']
            if status == 'format_error':
                try: parse_turn(attempt['response'], require_reasoning=reasoning)
                except FormatError as exc:
                    check(attempt['error'] == str(exc))
                    repair = format_repair(attempt['response'], exc, reasoning=reasoning)
                else: check(False)
            elif status == 'accepted':
                check(i == len(rd['attempts']))
                accepted_response = attempt['response']
                accepted = parse_turn(accepted_response, require_reasoning=reasoning); repair = None
            else:
                check(status in ('requesting', 'received', 'technical_error', 'interrupted', 'fatal'))
                if status in ('requesting', 'received', 'fatal'):
                    check(i == len(rd['attempts']) and rd['phase'] == 'generation')
        check(rd['repair'] == repair)
        if rd['phase'] == 'generation':
            check(not rd['tools'])
            continue  # Accepted response may be durable before message commit.
        check(accepted is not None and len(rd['tools']) == len(accepted.tool_calls))
        messages.append(assistant_message(accepted, accepted_response, reasoning=reasoning))
        pending = False
        for call, tool in zip(accepted.tool_calls, rd['tools']):
            if tool['status'] == 'done':
                check(not pending and isinstance(tool['observation'], str))
                messages.append({'role': 'tool', 'tool_call_id': call.call_id,
                                 'name': call.name, 'content': tool['observation']}); calls += 1
            else:
                check(tool['status'] in ('pending', 'started')); pending = True
        check(rd['phase'] != 'done' or not pending)
    check(state['messages'] == messages and state['calls'] == calls)

src/adapters/officeqa/local.py:
"""Thin adapter over the pinned SkillOpt OfficeQA local tools; no model calls."""
import calendar
import re
from pathlib import Path
from urllib.parse import parse_qs, urlparse

from skillopt.envs.officeqa import tool_runtime as upstream


def lines(value):
    if isinstance(value, list):
        return [str(x).strip() for x in value if str(x).strip()]
    return [x.strip() for x in str(value or '').splitlines() if x.strip()]


def source_references(source_files, source_docs, *, allow_url_sources=False):
    """Resolve each FRASER URL by bulletin month/year, never list position.

    Ordinarily the derived name must be in the declared source files. During
    explicit data repair, allow_url_sources permits files named by existing
    source URLs, with all additions recorded in the preparation report.
    """
    files, docs = lines(source_files), lines(source_docs)
    if not files or not docs:
        raise ValueError('Source files and page URLs must be nonempty')
    if any(Path(name).name != name for name in files):
        raise ValueError('Source file must be a basename')
    months = {m.lower(): f'{i:02d}' for i, m in enumerate(calendar.month_name) if m}
    result = []
    for url in docs:
        parsed = urlparse(url)
        match = re.fullmatch(r'([a-z]+)-(\d{4})-\d+', parsed.path.rstrip('/').split('/')[-1])
        if parsed.hostname != 'fraser.stlouisfed.org' or not match or match[1] not in months:
            raise ValueError(f'Unrecognized FRASER source URL: {url}')
        name = f'treasury_bulletin_{match[2]}_{months[match[1]]}.txt'
        pages = parse_qs(parsed.query).get('page', [])
        if (name not in files and not allow_url_sources) or len(pages) != 1 or not pages[0].isdigit() or int(pages[0]) < 1:
            raise ValueError(f'Unresolved source file/page: {url}')
        result.append((name, int(pages[0]), url))
    if not set(files) <= {r[0] for r in result}:
        raise ValueError('Some declared files have no matching source URL')
    return result


def aligned_item(item):
    """Return a copy compatible with the unmodified upstream positional reader."""
    refs = source_references(item['source_files'], item['source_docs'], allow_url_sources=True)
    legacy = upstream._iter_oracle_refs(item['source_files'], item['source_docs'])
    result = dict(item)
    if refs != legacy:
        result['source_files'] = [name for name, _, _ in refs]
    return result, refs, legacy


class LocalDocuments:
    """Explicit single corpus and nonempty per-task allowlist.

    Missing assets are preparation errors. Never pass an empty allowlist to
    upstream, where it would expand access to every file in the corpus.
    """
    def __init__(self, parsed_root, item):
        self.parsed_root = Path(parsed_root).resolve()
        self.text_root = self.parsed_root / 'transformed'
        self.files = list(dict.fromkeys(lines(item['source_files'])))
        if not self.files:
            raise ValueError('Empty source-file allowlist')
        self.paths = []
        for name in self.files:
            if Path(name).name != name:
                raise ValueError('Source file must be a basename')
            path = (self.text_root / name).resolve()
            if not path.is_relative_to(self.text_root.resolve()) or not path.is_file():
                raise ValueError(f'Missing or out-of-corpus source file: {name}')
            self.paths.append(str(path))

    def call(self, name, arguments):
        if name not in {'glob', 'read', 'grep'}:
            raise ValueError(f'Unsupported local tool: {name}')
        if name in {'read', 'grep'}:
            path = str(Path(str(arguments.get('path') or '')).resolve())
            if path not in self.paths:
                return name, f'[{name} error: path not allowed]'
        return upstream.run_tool(name, arguments, allowed_roots=[str(self.text_root)], allowed_files=self.files)

    def pages(self, item):
        refs = source_references(item['source_files'], item['source_docs'])
        for name, page, _ in refs:
            path = self.parsed_root / 'jsons' / (Path(name).stem + '.json')
            if not path.is_file() or not upstream._render_parsed_page(str(path), page):
                raise ValueError(f'Missing or empty parsed source page: {name}:{page}')
        return upstream.build_oracle_parsed_pages_context(
            [r[0] for r in refs], [r[2] for r in refs], [str(self.text_root)],
            evidence_note='Treat it as primary document evidence and combine it with local document tool evidence when useful.',
        )

src/adapters/officeqa/retry.py:
"""Six durable attempts per Actor round, with temporary format correction."""
from copy import deepcopy
from dataclasses import asdict
import json
import time

from skilladam.backends import openai_compatible as native
from skilladam.benchmarks.officeqa.rollout import TOOL_SCHEMAS

from .execution import REQUEST_ATTEMPTS
from .transport import RequestFailure


class GenerationExhausted(RuntimeError):
    pass


class FormatError(ValueError):
    pass


def retry_wait(number):
    time.sleep(2 * number)


def parse_turn(response, *, require_reasoning=False):
    """Validate the whole response before allowing any tool execution.

    Tool *argument values* remain the native tool's responsibility. This only
    validates the call protocol, not read windows, paths or answer correctness.
    """
    if not isinstance(response, dict):
        raise RequestFailure('Malformed API response envelope')
    choices = response.get('choices')
    if not isinstance(choices, list) or len(choices) != 1 or not isinstance(choices[0], dict):
        raise RequestFailure('API response must contain one choice')
    choice = choices[0]
    finish = choice.get('finish_reason')
    if finish in (None, 'length'):
        raise RequestFailure('Missing finish reason or truncated response')
    if finish not in ('stop', 'tool_calls'):
        raise RequestFailure('Non-retryable finish reason', retryable=False)
    message = choice.get('message')
    if not isinstance(message, dict) or not isinstance(message.get('content', ''), (str, type(None))):
        raise RequestFailure('Malformed API message')
    if message.get('refusal'):
        raise RequestFailure('Provider refusal', retryable=False)
    if require_reasoning and not isinstance(message.get('reasoning_content'), str):
        raise RequestFailure('Missing or invalid DeepSeek reasoning_content')
    # Invalid usage belongs to the API envelope, not model format feedback.
    try:
        native.normalize_usage(response.get('usage'), requests=1)
    except ValueError:
        raise RequestFailure('Invalid API usage') from None
    calls = message.get('tool_calls')
    if calls is not None and not isinstance(calls, list):
        raise FormatError('tool_calls must be a JSON array (list) or null')
    if not calls and not (message.get('content') or '').strip():
        raise RequestFailure('Empty response')
    try:
        turn = native._officeqa_turn(response)
    except native.BackendProtocolError as exc:
        raise FormatError(str(exc)) from None
    ids = [call.call_id for call in turn.tool_calls]
    if len(ids) != len(set(ids)):
        raise FormatError('Tool call IDs must be unique within the response')
    names = {schema['function']['name'] for schema in TOOL_SCHEMAS}
    if any(call.name not in names for call in turn.tool_calls):
        raise FormatError('Tool names must be glob, read or grep')
    if finish == 'tool_calls' and not turn.tool_calls:
        raise FormatError('tool_calls finish reason requires function calls')
    return turn


def assistant_message(turn, response=None, *, reasoning=False):
    value = {'role': 'assistant', 'content': turn.text}
    if turn.tool_calls:
        value['content'] = turn.text or None
        value['tool_calls'] = [{'id': c.call_id, 'type': 'function',
            'function': {'name': c.name, 'arguments': c.raw_arguments}} for c in turn.tool_calls]
    if reasoning:
        value['reasoning_content'] = response['choices'][0]['message']['reasoning_content']
    return value


def format_repair(response, error, *, reasoning=False):
    message = deepcopy(response['choices'][0]['message'])
    saved = {}
    if reasoning:
        saved['reasoning_content'] = message.pop('reasoning_content')
    return {'output': json.dumps(message, ensure_ascii=False), 'error': str(error), **saved}


def request_messages(messages, repair):
    if repair is None:
        return deepcopy(messages)
    # Serialize invalid calls as text; never send dangling/malformed native
    # tool_calls back to an API that requires matching tool observations.
    assistant = {'role': 'assistant', 'content': repair['output']}
    if 'reasoning_content' in repair:
        assistant['reasoning_content'] = repair['reasoning_content']
    return deepcopy(messages) + [
        assistant,
        {'role': 'user', 'content': '# Previous Tool Call Validation Error\n\n' + repair['error'] +
         '\nNo tools from this response were executed. Correct the call structure and return a complete '
         'response under the original tool/answer contract. This diagnostic is not task evidence.'},
    ]


def generate_round(round_state, messages, transport, save):
    attempts = round_state['attempts']
    reasoning = transport.metadata()['reasoning_mode'] == 'deepseek_thinking'
    while True:
        last = attempts[-1] if attempts else None
        if last and last['status'] == 'accepted':
            return parse_turn(last['response'], require_reasoning=reasoning)
        if last and last['status'] == 'fatal':
            raise RequestFailure(last['error'], retryable=False)
        if last and last['status'] == 'requesting':
            # Process died with no durable response. Count the request anyway.
            last.update(status='interrupted', error='Request outcome unknown; attempt remains consumed')
            save()
        if last and last['status'] == 'received':
            try:
                turn = parse_turn(last['response'], require_reasoning=reasoning)
            except FormatError as exc:
                round_state['repair'] = format_repair(last['response'], exc, reasoning=reasoning)
                last.update(status='format_error', error=str(exc))
            except RequestFailure as exc:
                last.update(status='technical_error' if exc.retryable else 'fatal', error=str(exc))
            else:
                last['status'] = 'accepted'
                round_state['repair'] = None
                save()
                return turn
            save()
            continue
        if len(attempts) >= REQUEST_ATTEMPTS:
            raise GenerationExhausted('Six request attempts exhausted; resume does not reset the budget')
        if attempts:
            retry_wait(len(attempts))
        attempt = {'number': len(attempts) + 1, 'status': 'requesting',
                   'messages': request_messages(messages, round_state['repair']),
                   'usage': asdict(native.normalize_usage(None, requests=1))}
        attempts.append(attempt)
        save()  # Reserve the attempt BEFORE making the request.
        try:
            response = transport(messages=deepcopy(attempt['messages']), tools=deepcopy(TOOL_SCHEMAS))
        except RequestFailure as exc:
            attempt.update(status='technical_error' if exc.retryable else 'fatal', error=str(exc), evidence=exc.evidence)
            save()
        except Exception as exc:
            # Programming/disk/fixture errors must not manufacture another call.
            attempt.update(status='fatal', error=type(exc).__name__)
            save()
            raise
        else:
            attempt.update(status='received', response=response)
            if isinstance(response, dict):
                try:
                    attempt['usage'] = asdict(native.normalize_usage(response.get('usage'), requests=1))
                except ValueError:
                    pass
            save()  # Recovery parses this response without issuing a new call.

